def _normalize_source(item):
    """Return a source dict with the fields the frontend expects."""
    if isinstance(item, dict):
        source = dict(item)
    else:
        source = {"chunk_id": item}
    source.setdefault("chunk_id", None)
    source.setdefault("source", "unknown")
    source.setdefault("page", None)
    source.setdefault("retrieval_reason", "semantic")
    if source.get("retrieval_reason") is None:
        source["retrieval_reason"] = "semantic"
    return source


def build_response(answer, results, triples, evidence_level):
    sources = [_normalize_source(item) for item in (results or [])]
    return {
        "status": "ok",
        "answer": answer,
        "sources": sources,
        "related_triples": list(triples or []),
        "evidence_level": evidence_level,
    }


def _format_source(source):
    if not isinstance(source, dict):
        return str(source)
    name = source.get("source") or "unknown"
    page = source.get("page")
    reason = source.get("retrieval_reason") or "semantic"
    location = f"{name} p.{page}" if page is not None else str(name)
    return f"{location} ({reason})"


def render_response(payload):
    if not isinstance(payload, dict):
        return str(payload)

    status = payload.get("status", "ok")
    if status == "error":
        return f"Error: {payload.get('error', 'unknown error')}"

    lines = []
    answer = payload.get("answer")
    lines.append("" if answer is None else str(answer))

    sources = payload.get("sources") or []
    if sources:
        lines.append("Sources:")
        for source in sources:
            lines.append(f"- {_format_source(source)}")

    triples = payload.get("related_triples") or []
    if triples:
        lines.append("Related triples:")
        for triple in triples:
            if isinstance(triple, (list, tuple)):
                lines.append("- " + " -> ".join(str(part) for part in triple))
            elif isinstance(triple, dict):
                subject = triple.get("subject", triple.get("head", ""))
                predicate = triple.get("predicate", triple.get("relation", ""))
                obj = triple.get("object", triple.get("tail", ""))
                lines.append(f"- {subject} -> {predicate} -> {obj}")
            else:
                lines.append(f"- {triple}")

    evidence_level = payload.get("evidence_level")
    if evidence_level is not None:
        lines.append(f"Evidence level: {evidence_level}")

    return "\n".join(lines)
